<?php
declare(strict_types=1);require dirname(__DIR__,2).'/src/bootstrap.php';
use Sedema\Authorization;use Sedema\Payments\PaymentContext;use Sedema\Payments\PaymentPage;
$c=PaymentContext::boot();$user=$c['user'];$repo=$c['repository'];$search=mb_substr(trim((string)($_GET['search']??'')),0,100);$status=(string)($_GET['status']??'pending');if(!in_array($status,['pending','paid','all'],true))$status='pending';$orders=$repo->orders($search,$status);PaymentPage::begin('Pagos y cobranzas','payments',$user);?>
<section class="inventory-heading"><div><p class="section-kicker">Cobranza</p><h2>Pagos de pedidos</h2><p>Registrá cobros, verificá operaciones electrónicas y consultá saldos.</p></div></section>
<form class="inventory-toolbar" method="get"><div class="toolbar-search field"><label>Buscar pedido</label><input name="search" value="<?=e($search)?>" placeholder="Nº pedido, cliente o DNI/CUIT"></div><div class="field"><label>Estado</label><select name="status"><option value="pending" <?=$status==='pending'?'selected':''?>>Pendientes</option><option value="paid" <?=$status==='paid'?'selected':''?>>Pagados</option><option value="all" <?=$status==='all'?'selected':''?>>Todos</option></select></div><button class="button button-primary button-filter">Aplicar</button></form>
<section class="inventory-panel"><div class="panel-title-row"><div><h3>Pedidos</h3><p><?=count($orders)?> resultados</p></div></div><div class="inventory-table-wrap"><table class="inventory-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Total</th><th>Pagado</th><th>Saldo</th><th>Estado</th><th></th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="7">No hay pedidos para mostrar.</td></tr><?php endif;?><?php foreach($orders as $o):?><tr><td><strong>#<?= (int)$o['idPedido']?></strong><span class="cell-meta"><?=e((string)$o['fecha'])?></span></td><td><strong><?=e($o['apellido'].', '.$o['nombre'])?></strong><span class="cell-meta"><?=e((string)$o['cuitDNI'])?></span></td><td>$<?=number_format((float)$o['total'],2,',','.')?></td><td>$<?=number_format((float)$o['pagado'],2,',','.')?></td><td><strong>$<?=number_format((float)$o['saldo'],2,',','.')?></strong></td><td><?=e((string)$o['estado'])?></td><td><?php if(Authorization::can($user,'payments.manage')):?><a class="table-link" href="collect.php?id=<?=(int)$o['idPedido']?>"><?=((float)$o['saldo']>0.004)?'Cobrar':'Ver pagos'?></a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php PaymentPage::end(); ?>
